import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-11-03","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/03.md","filePath":"notes/kernel-digest/2026/11/03.md"}'),l={name:"notes/kernel-digest/2026/11/03.md"};function n(s,e,d,c,i,m){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-03" tabindex="-1">Kernel 日报 2026-11-03 <a class="header-anchor" href="#kernel-日报-2026-11-03" aria-label="Permalink to &quot;Kernel 日报 2026-11-03&quot;">​</a></h1><blockquote><p>生成时间：2026-11-03T01:20:10Z｜共 57 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-03 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_8563f29ab924-·-managing-the-kernel-cve-flood" tabindex="-1"><code>8563f29ab924</code> · <a href="https://lwn.net/Articles/1100894/" target="_blank" rel="noreferrer">[$] Managing the kernel CVE flood</a> <a class="header-anchor" href="#_8563f29ab924-·-managing-the-kernel-cve-flood" aria-label="Permalink to &quot;`8563f29ab924` · [[$] Managing the kernel CVE flood](https://lwn.net/Articles/1100894/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>在 2026 Linux Plumbers Conference 上，Amazon 工程师 Dylan Johnson 和 Justinien Bouron 从维护 AWS 安全运行的角度讨论了如何应对海量 kernel CVE 披露。内核社区长期建议运行最新内核，这一策略在实践中确实有效——但只是勉强有效。</p><blockquote><p><strong>学习价值</strong>：展示了大规模生产环境如何实际处理内核 CVE 洪流，对理解内核漏洞管理流程与运维实践很有价值。</p></blockquote><h3 id="bdcde41eeb06-·-patch-net-v4-0-7-psp-tls-don-t-send-offloaded-contents-in-cleartext" tabindex="-1"><code>bdcde41eeb06</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 0/7] psp, tls: don&#39;t send offloaded contents in cleartext</a> <a class="header-anchor" href="#bdcde41eeb06-·-patch-net-v4-0-7-psp-tls-don-t-send-offloaded-contents-in-cleartext" aria-label="Permalink to &quot;`bdcde41eeb06` · [[PATCH net v4 0/7] psp, tls: don&#39;t send offloaded contents in cleartext](https://lore.kernel.org/all/20261103001143.246081-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev｜网络</em></p><p>该系列补丁修复多个 crypto offload 路径上数据包可能以明文发送的问题，包括 IPv6 扩展头、IPv4 分片和 ICMP 等场景。作者在开发 socket-less PSP association 支持时发现这些问题，由于 tx/tls association 表达了加密意图，这些绕过加密的情况都需修复。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 PSP/TLS offload 明文泄漏的多种场景，适合系统性了解传输层加密 offload 的边界条件。</p></blockquote><h3 id="_7e4e53192e64-·-patch-v3-00-10-liveupdate-preserve-tmpfs-files-across-live-update" tabindex="-1"><code>7e4e53192e64</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-1-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 00/10] liveupdate: Preserve tmpfs files across Live Update</a> <a class="header-anchor" href="#_7e4e53192e64-·-patch-v3-00-10-liveupdate-preserve-tmpfs-files-across-live-update" aria-label="Permalink to &quot;`7e4e53192e64` · [[PATCH v3 00/10] liveupdate: Preserve tmpfs files across Live Update](https://lore.kernel.org/all/20261103010216.3447716-1-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm｜内存管理</em></p><p>本系列补丁使 tmpfs 挂载点上的文件（而不仅是 memfd）能在 Live Update 过程中被保留。当前 memfd 文件 handler 只接受未链接的 shmem 文件，且 LIVEUPDATE_SESSION_RETRIEVE_FD 总是将其恢复为匿名 memfd，导致内存日志、二进制和配置文件等 tmpfs 文件无法保留。内核通过 KHO（Kexec HandOver）机制保留文件内容。</p><blockquote><p><strong>学习价值</strong>：了解 LUO/KHO 这类内核热更新基础设施如何跨 kexec 保留状态，是 shmem 与 tmpfs 实现的进阶学习材料。</p></blockquote><h3 id="_02f00b3181dd-·-the-second-part-of-the-7-4-merge-window" tabindex="-1"><code>02f00b3181dd</code> · <a href="https://lwn.net/Articles/1102739/" target="_blank" rel="noreferrer">[$] The second part of the 7.4 merge window</a> <a class="header-anchor" href="#_02f00b3181dd-·-the-second-part-of-the-7-4-merge-window" aria-label="Permalink to &quot;`02f00b3181dd` · [[$] The second part of the 7.4 merge window](https://lwn.net/Articles/1102739/)&quot;">​</a></h3><p><em>daroc｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>Linux 7.4 合并窗口于 11 月 1 日关闭，共合入 18,591 个非 merge changesets，几乎追平 7.3 周期 18,765 的历史纪录。其中 11,838 个落在合并窗口后半段，且大部分是各类 bug 修复，显示修复工作似乎正在挤占新特性的空间。尽管如此，窗口末期仍合入了不少新特性，也移除了一些旧功能。</p><blockquote><p><strong>学习价值</strong>：通过合并窗口统计可以观察内核开发节奏与 bug 修复占比趋势，是理解内核发布流程的直观素材。</p></blockquote><h3 id="c18d224c7e82-·-patch-0-4-gpu-nova-core-gsp-add-support-for-gmc-messages" tabindex="-1"><code>c18d224c7e82</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-0-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 0/4] gpu: nova-core: gsp: add support for GMC messages</a> <a class="header-anchor" href="#c18d224c7e82-·-patch-0-4-gpu-nova-core-gsp-add-support-for-gmc-messages" aria-label="Permalink to &quot;`c18d224c7e82` · [[PATCH 0/4] gpu: nova-core: gsp: add support for GMC messages](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-0-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列从 John Hubbard 的 r000 系列 v3 中提取 patch 9-12，为 nova-core 添加 GMC GSP 消息协议支持，并 rebase 到最新的 drm-rust-next 分支。GMC 是 r000 固件用于 boot protocol 和新接口的消息类型，拥有独立 header。该系列不引入功能性变化，新代码在切换到 r000 前保持休眠状态。</p><blockquote><p><strong>学习价值</strong>：展示了大型 patch 系列如何拆分重组以便于 review，以及 DRM 子系统中休眠代码的渐进式合入策略。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（21 条）</li><li><strong>网络</strong>（13 条）</li><li><strong>文件系统与存储</strong>（1 条）</li><li><strong>Rust in Linux</strong>（10 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（11 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_92e3aff806a0-·-patch-v3-08-10-mm-shmem-luo-allow-preserving-tmpfs-files-that-are-still-linked" tabindex="-1"><code>92e3aff806a0</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-9-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 08/10] mm/shmem_luo: Allow preserving tmpfs files that are still linked</a> <a class="header-anchor" href="#_92e3aff806a0-·-patch-v3-08-10-mm-shmem-luo-allow-preserving-tmpfs-files-that-are-still-linked" aria-label="Permalink to &quot;`92e3aff806a0` · [[PATCH v3 08/10] mm/shmem_luo: Allow preserving tmpfs files that are still linked](https://lore.kernel.org/all/20261103010216.3447716-9-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜lkml</em></p><p>扩展 shmem_luo（Live Update of tmpfs 文件）支持保留仍处于 linked 状态的 tmpfs 文件。保留文件要求写权限且文件以读方式打开，并拒绝 append-only 文件。此前仅接受无链接文件（如 unlinked 文件和 O_TMPFILE 创建的文件），此改动让用户态无需先 unlink 即可保留文件并继续通过路径使用，但文件路径本身不被保留，恢复后需由用户态选择目标 tmpfs 挂载点。</p><blockquote><p><strong>学习价值</strong>：展示了 live update 场景下 tmpfs 文件保留的权限与生命周期设计权衡，对理解 shmem 文件状态与 LUO 机制很有价值。</p></blockquote><h3 id="d9f22b2dbac6-·-patch-v3-09-10-mm-shmem-luo-allow-retrieving-tmpfs-files-with-o-rdonly" tabindex="-1"><code>d9f22b2dbac6</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-10-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 09/10] mm/shmem_luo: Allow retrieving tmpfs files with O_RDONLY</a> <a class="header-anchor" href="#d9f22b2dbac6-·-patch-v3-09-10-mm-shmem-luo-allow-retrieving-tmpfs-files-with-o-rdonly" aria-label="Permalink to &quot;`d9f22b2dbac6` · [[PATCH v3 09/10] mm/shmem_luo: Allow retrieving tmpfs files with O_RDONLY](https://lore.kernel.org/all/20261103010216.3447716-10-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜lkml</em></p><p>允许用户态在 struct liveupdate_shmem_retrieve_arg 中指定 O_RDONLY，以只读方式取回 tmpfs 文件。实现上先以可写方式创建文件（open() 对 O_TMPFILE 要求写权限），再用 dentry_open() 以原文件规范化后的 flags 重新打开为只读并丢弃可写文件，且不额外检查权限。只读取回使恢复的二进制文件可在 live update 会话完成前即被执行。</p><blockquote><p><strong>学习价值</strong>：演示了文件重新打开（reopen）与权限语义在内核中的精细处理，对学习 dentry_open 与文件访问模式很有帮助。</p></blockquote><h3 id="_48a41fb88843-·-patch-v3-07-10-mm-shmem-luo-retrieve-tmpfs-files-onto-a-tmpfs-mount-chosen-by-userspace" tabindex="-1"><code>48a41fb88843</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-8-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 07/10] mm/shmem_luo: Retrieve tmpfs files onto a tmpfs mount chosen by userspace</a> <a class="header-anchor" href="#_48a41fb88843-·-patch-v3-07-10-mm-shmem-luo-retrieve-tmpfs-files-onto-a-tmpfs-mount-chosen-by-userspace" aria-label="Permalink to &quot;`48a41fb88843` · [[PATCH v3 07/10] mm/shmem_luo: Retrieve tmpfs files onto a tmpfs mount chosen by userspace](https://lore.kernel.org/all/20261103010216.3447716-8-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜lkml</em></p><p>让 shmem_luo 取回的 tmpfs 文件落到用户态指定的 tmpfs 挂载点上，而非作为 memfd 放在内核内部 tmpfs 挂载。新增 struct liveupdate_shmem_retrieve_arg 作为 LIVEUPDATE_SESSION_RETRIEVE_FD 的参数，并通过 SHMEM_LUO_FLAG_TMPFS 标志（基于文件 superblock）记录文件来源挂载类型。O_TMPFILE 创建的文件其原挂载已不存在，因此按 memfd 处理。</p><blockquote><p><strong>学习价值</strong>：展示了 LUO 文件恢复的挂载点选择设计，有助于理解 tmpfs superblock 与 memfd 的关系。</p></blockquote><h3 id="_586c3a5b6931-·-patch-v3-10-10-selftests-liveupdate-add-a-test-for-preserving-tmpfs-files" tabindex="-1"><code>586c3a5b6931</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-11-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 10/10] selftests/liveupdate: Add a test for preserving tmpfs files</a> <a class="header-anchor" href="#_586c3a5b6931-·-patch-v3-10-10-selftests-liveupdate-add-a-test-for-preserving-tmpfs-files" aria-label="Permalink to &quot;`586c3a5b6931` · [[PATCH v3 10/10] selftests/liveupdate: Add a test for preserving tmpfs files](https://lore.kernel.org/all/20261103010216.3447716-11-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>新增 luo_tmpfs kexec 自测，覆盖 tmpfs 文件与 memfd 的保留及通过 struct liveupdate_shmem_retrieve_arg 取回到指定 tmpfs 挂载的流程。测试分两个阶段：阶段 1 保留各用例的源文件；阶段 2 在各自独立目录和 tmpfs 挂载中运行用例，以便用 statfs() 和 st_blocks 精确检查块使用。用例覆盖恢复文件的内容、大小、位置、seals 与 holes，以及文件创建语义（类似 open(O_TMPFILE)，mode 减去 umask）。</p><blockquote><p><strong>学习价值</strong>：一份结构清晰的自测设计范例，展示如何用 kexec 两阶段流程验证跨 live update 的文件状态一致性。</p></blockquote><h3 id="_09d84debfa07-·-patch-v3-06-10-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" tabindex="-1"><code>09d84debfa07</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-7-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 06/10] mm/shmem_luo: Don&#39;t make early retrieve failures permanent</a> <a class="header-anchor" href="#_09d84debfa07-·-patch-v3-06-10-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" aria-label="Permalink to &quot;`09d84debfa07` · [[PATCH v3 06/10] mm/shmem_luo: Don&#39;t make early retrieve failures permanent](https://lore.kernel.org/all/20261103010216.3447716-7-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>将 shmem_luo_retrieve() 在开始恢复 folios 之前的失败标记为可重试，返回错误但不释放序列化状态；若无任何取回成功，则由 finish() 释放保留的 folios。由于 folios 恢复前保留状态未被消费，取回可以重试。这同时修复了早期步骤失败（如文件带有本内核不支持的 seals）时保留 folios 泄漏的问题。</p><blockquote><p><strong>学习价值</strong>：展示了错误处理中“可重试失败”与“永久失败”的区分，以及如何避免资源泄漏，是内核错误路径设计的良好教材。</p></blockquote><h3 id="_4a7e01926b51-·-patch-v3-05-10-liveupdate-don-t-warn-if-tracking-a-retrieved-file-fails" tabindex="-1"><code>4a7e01926b51</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-6-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 05/10] liveupdate: Don&#39;t WARN if tracking a retrieved file fails</a> <a class="header-anchor" href="#_4a7e01926b51-·-patch-v3-05-10-liveupdate-don-t-warn-if-tracking-a-retrieved-file-fails" aria-label="Permalink to &quot;`4a7e01926b51` · [[PATCH v3 05/10] liveupdate: Don&#39;t WARN if tracking a retrieved file fails](https://lore.kernel.org/all/20261103010216.3447716-6-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>将取回文件加入 luo_preserved_files 失败（如 xa_insert() 返回 -ENOMEM）时不再触发 WARN_ON()，而是将其标记为永久失败并保留文件直到文件集结束。因为用户态可通过 LIVEUPDATE_SESSION_RETRIEVE_FD 触发该失败，WARN 会让 panic_on_warn 系统崩溃；且此时保留状态已被消费无法重试，保留文件可确保资源不会提前释放。</p><blockquote><p><strong>学习价值</strong>：强调用户态可触发的失败路径不应使用 WARN，是内核健壮性与 panic_on_warn 语义的实用案例。</p></blockquote><h3 id="ca798d24a9ad-·-patch-v3-04-10-mm-rename-memfd-luo-to-shmem-luo" tabindex="-1"><code>ca798d24a9ad</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-5-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 04/10] mm: Rename memfd_luo to shmem_luo</a> <a class="header-anchor" href="#ca798d24a9ad-·-patch-v3-04-10-mm-rename-memfd-luo-to-shmem-luo" aria-label="Permalink to &quot;`ca798d24a9ad` · [[PATCH v3 04/10] mm: Rename memfd_luo to shmem_luo](https://lore.kernel.org/all/20261103010216.3447716-5-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>将 memfd Live Update 文件处理器从 memfd_luo 重命名为 shmem_luo，包括源文件、KHO ABI 头文件、文档和 Kconfig 选项（CONFIG_LIVEUPDATE_MEMFD 改为 CONFIG_LIVEUPDATE_SHMEM）。原因是该处理器实际保留的是 shmem 文件，后续提交将其扩展到 tmpfs 挂载上的其他文件，memfd 名称会造成误导；且以文件系统命名也为将来独立的 hugetlbfs（MFD_HUGETLB）处理器留出空间。</p><blockquote><p><strong>学习价值</strong>：一个典型的纯重命名补丁，说明命名应反映实际抽象范围，对理解 shmem/memfd/tmpfs 的层次关系有帮助。</p></blockquote><h3 id="_3b33c4a176c3-·-patch-v3-03-10-liveupdate-allow-file-handlers-to-mark-retrieve-failures-as-retryable" tabindex="-1"><code>3b33c4a176c3</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-4-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 03/10] liveupdate: Allow file handlers to mark retrieve failures as retryable</a> <a class="header-anchor" href="#_3b33c4a176c3-·-patch-v3-03-10-liveupdate-allow-file-handlers-to-mark-retrieve-failures-as-retryable" aria-label="Permalink to &quot;`3b33c4a176c3` · [[PATCH v3 03/10] liveupdate: Allow file handlers to mark retrieve failures as retryable](https://lore.kernel.org/all/20261103010216.3447716-4-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本补丁允许 LUO（Live Update Orchestrator）的文件 handler 在 .retrieve() 回调失败时将错误标记为可重试。此前 luo_retrieve_file() 一旦失败会将错误记录在 luo_file-&gt;retrieve_status 并阻止后续 retrieve 尝试，但对于在触碰任何 preserved KHO 状态之前就因参数校验失败（如缺少参数、无效或只读目标 fd、目标文件非空）而提前返回的情况，应允许重试。</p><blockquote><p><strong>学习价值</strong>：展示了内核子系统如何区分可恢复错误与不可恢复错误，是学习错误处理策略设计的好例子。</p></blockquote><h3 id="_2242a1292569-·-patch-v3-02-10-selftests-liveupdate-add-tests-for-preserve-and-retrieve-user-argument" tabindex="-1"><code>2242a1292569</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-3-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 02/10] selftests: liveupdate: Add tests for preserve and retrieve user argument</a> <a class="header-anchor" href="#_2242a1292569-·-patch-v3-02-10-selftests-liveupdate-add-tests-for-preserve-and-retrieve-user-argument" aria-label="Permalink to &quot;`2242a1292569` · [[PATCH v3 02/10] selftests: liveupdate: Add tests for preserve and retrieve user argument](https://lore.kernel.org/all/20261103010216.3447716-3-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 LIVEUPDATE_SESSION_PRESERVE_FD 和 LIVEUPDATE_SESSION_RETRIEVE_FD 的用户参数支持添加 selftests。在 libliveupdate 中新增 luo_session_preserve_fd_arg() 和 luo_session_retrieve_fd_arg() 辅助函数，并添加 preserve_memfd_with_arg 测试用例，验证 memfd 保留对非零参数返回 -EOPNOTSUPP、显式零参数可接受、且与仅传到 token 字段的旧版 struct 大小保持兼容。</p><blockquote><p><strong>学习价值</strong>：演示了如何为内核新特性编写 selftests，特别是向后兼容性（legacy struct size）的测试思路。</p></blockquote><h3 id="c8d38cd7a864-·-patch-v3-01-10-liveupdate-pass-user-argument-to-file-preserve-and-retrieve" tabindex="-1"><code>c8d38cd7a864</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-2-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 01/10] liveupdate: Pass user argument to file preserve and retrieve</a> <a class="header-anchor" href="#c8d38cd7a864-·-patch-v3-01-10-liveupdate-pass-user-argument-to-file-preserve-and-retrieve" aria-label="Permalink to &quot;`c8d38cd7a864` · [[PATCH v3 01/10] liveupdate: Pass user argument to file preserve and retrieve](https://lore.kernel.org/all/20261103010216.3447716-2-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>允许用户态在通过 LUO 保留或取回 FD 时传递文件 handler 特定的参数结构。扩展 struct liveupdate_session_preserve_fd 和 struct liveupdate_session_retrieve_fd，增加 64 位 arg 字段指向 handler 定义的参数，避免为每种文件类型引入单独的 ioctl。参数是必需、可选还是未使用由各文件 handler 自行定义。</p><blockquote><p><strong>学习价值</strong>：体现了内核 UAPI 扩展的常见模式：通过可变长度参数结构避免 ioctl 接口爆炸，值得学习。</p></blockquote><h3 id="_7e4e53192e64-·-patch-v3-00-10-liveupdate-preserve-tmpfs-files-across-live-update-1" tabindex="-1"><code>7e4e53192e64</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-1-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 00/10] liveupdate: Preserve tmpfs files across Live Update</a> <a class="header-anchor" href="#_7e4e53192e64-·-patch-v3-00-10-liveupdate-preserve-tmpfs-files-across-live-update-1" aria-label="Permalink to &quot;`7e4e53192e64` · [[PATCH v3 00/10] liveupdate: Preserve tmpfs files across Live Update](https://lore.kernel.org/all/20261103010216.3447716-1-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>本系列补丁使 tmpfs 挂载点上的文件（而不仅是 memfd）能在 Live Update 过程中被保留。当前 memfd 文件 handler 只接受未链接的 shmem 文件，且 LIVEUPDATE_SESSION_RETRIEVE_FD 总是将其恢复为匿名 memfd，导致内存日志、二进制和配置文件等 tmpfs 文件无法保留。内核通过 KHO（Kexec HandOver）机制保留文件内容。</p><blockquote><p><strong>学习价值</strong>：了解 LUO/KHO 这类内核热更新基础设施如何跨 kexec 保留状态，是 shmem 与 tmpfs 实现的进阶学习材料。</p></blockquote><h3 id="_306c186fb69d-·-patch-v2-7-8-docs-mm-damon-maintainer-profile-fix-subject-verb-agreement" tabindex="-1"><code>306c186fb69d</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-8-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 7/8] Docs/mm/damon/maintainer-profile: fix subject-verb agreement</a> <a class="header-anchor" href="#_306c186fb69d-·-patch-v2-7-8-docs-mm-damon-maintainer-profile-fix-subject-verb-agreement" aria-label="Permalink to &quot;`306c186fb69d` · [[PATCH v2 7/8] Docs/mm/damon/maintainer-profile: fix subject-verb agreement](https://lore.kernel.org/all/20261103005940.91432-8-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON maintainer-profile 文档中的主谓一致问题：&quot;The DAMON maintainer usually work&quot; 应为 &quot;works&quot;。这是 DAMON 文档系列语法清理的一部分。</p><blockquote><p><strong>学习价值</strong>：价值有限，但可作为初学者以文档修复切入内核社区贡献的入门途径。</p></blockquote><h3 id="_7b12949774f0-·-patch-v2-8-8-docs-mm-damon-monitoring-intervals-tuning-example-fix-grammar-and-typos" tabindex="-1"><code>7b12949774f0</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-9-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 8/8] Docs/mm/damon/monitoring_intervals_tuning_example: fix grammar and typos</a> <a class="header-anchor" href="#_7b12949774f0-·-patch-v2-8-8-docs-mm-damon-monitoring-intervals-tuning-example-fix-grammar-and-typos" aria-label="Permalink to &quot;`7b12949774f0` · [[PATCH v2 8/8] Docs/mm/damon/monitoring_intervals_tuning_example: fix grammar and typos](https://lore.kernel.org/all/20261103005940.91432-9-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON monitoring_intervals_tuning_example 文档中的若干拼写和语法错误，包括标题中的 &quot;Moniting&quot; 拼写，以及 &quot;starts looking degrading&quot; 改为 &quot;start looking degraded for&quot;，并对过长行重新折行。</p><blockquote><p><strong>学习价值</strong>：适合作为初学者通过 docs cleanup 参与内核贡献的参考示例。</p></blockquote><h3 id="e4b855847636-·-patch-v2-6-8-docs-mm-damon-api-fix-verb-form" tabindex="-1"><code>e4b855847636</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-7-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 6/8] Docs/mm/damon/api: fix verb form</a> <a class="header-anchor" href="#e4b855847636-·-patch-v2-6-8-docs-mm-damon-api-fix-verb-form" aria-label="Permalink to &quot;`e4b855847636` · [[PATCH v2 6/8] Docs/mm/damon/api: fix verb form](https://lore.kernel.org/all/20261103005940.91432-7-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON API 文档中的动词形式错误：&quot;All you need to do is include&quot; 而非 &quot;including&quot;。属于 DAMON 文档语法清理系列的一部分。</p><blockquote><p><strong>学习价值</strong>：典型的文档小修，展示了 trivial patch 的提交流程。</p></blockquote><h3 id="b82f69ae7d21-·-patch-v2-5-8-docs-mm-damon-design-fix-grammar-and-typos" tabindex="-1"><code>b82f69ae7d21</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-6-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 5/8] Docs/mm/damon/design: fix grammar and typos</a> <a class="header-anchor" href="#b82f69ae7d21-·-patch-v2-5-8-docs-mm-damon-design-fix-grammar-and-typos" aria-label="Permalink to &quot;`b82f69ae7d21` · [[PATCH v2 5/8] Docs/mm/damon/design: fix grammar and typos](https://lore.kernel.org/all/20261103005940.91432-6-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON design 文档中的语法和拼写问题，包括缺失动词的关系从句（如 &quot;pages that assumed to have&quot;、&quot;filters that handled by the core layer&quot;）、&quot;Parreto&quot; 拼写及 &quot;Use space&quot; 应为 &quot;User space&quot; 等。</p><blockquote><p><strong>学习价值</strong>：在修文档的同时可顺带阅读 DAMON 设计文档，理解其核心层与各模块的关系。</p></blockquote><h3 id="_31f6edf7d782-·-patch-v2-1-8-docs-admin-guide-mm-damon-start-fix-grammar" tabindex="-1"><code>31f6edf7d782</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-2-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 1/8] Docs/admin-guide/mm/damon/start: fix grammar</a> <a class="header-anchor" href="#_31f6edf7d782-·-patch-v2-1-8-docs-admin-guide-mm-damon-start-fix-grammar" aria-label="Permalink to &quot;`31f6edf7d782` · [[PATCH v2 1/8] Docs/admin-guide/mm/damon/start: fix grammar](https://lore.kernel.org/all/20261103005940.91432-2-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON 入门指南（admin-guide/mm/damon/start）中的若干语法错误，如 &quot;make DAMON monitors&quot; 和 &quot;that has not accessed&quot;，并将 &quot;The first two lines&quot; 更正为 &quot;The first line&quot; 以匹配仅剩一条 masim 命令的现状。</p><blockquote><p><strong>学习价值</strong>：DAMON 入门指南本身值得阅读，此补丁可帮助学习者找到权威的 DAMON 上手材料。</p></blockquote><h3 id="dc808abb205d-·-patch-v2-3-8-docs-admin-guide-mm-damon-usage-fix-grammar" tabindex="-1"><code>dc808abb205d</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-4-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 3/8] Docs/admin-guide/mm/damon/usage: fix grammar</a> <a class="header-anchor" href="#dc808abb205d-·-patch-v2-3-8-docs-admin-guide-mm-damon-usage-fix-grammar" aria-label="Permalink to &quot;`dc808abb205d` · [[PATCH v2 3/8] Docs/admin-guide/mm/damon/usage: fix grammar](https://lore.kernel.org/all/20261103005940.91432-4-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON usage 文档中的若干语法错误，主要涉及主谓一致和 &quot;be&quot; 动词的缺失或多余，并将 &quot;Below commands applies&quot; 改写为更通顺的 &quot;The commands below apply&quot;。</p><blockquote><p><strong>学习价值</strong>：文档清理类补丁，适合初学者了解 patch 提交格式与流程。</p></blockquote><h3 id="bbee1eb2b4bb-·-patch-v2-4-8-docs-admin-guide-mm-damon-lru-sort-fix-remaining-grammar" tabindex="-1"><code>bbee1eb2b4bb</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-5-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 4/8] Docs/admin-guide/mm/damon/lru_sort: fix remaining grammar</a> <a class="header-anchor" href="#bbee1eb2b4bb-·-patch-v2-4-8-docs-admin-guide-mm-damon-lru-sort-fix-remaining-grammar" aria-label="Permalink to &quot;`bbee1eb2b4bb` · [[PATCH v2 4/8] Docs/admin-guide/mm/damon/lru_sort: fix remaining grammar](https://lore.kernel.org/all/20261103005940.91432-5-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON LRU_SORT 管理文档中遗留的语法错误，如 &quot;should automatically activated&quot; 和 &quot;Make DAMON_LRU_SORT reads&quot; 等，并对过长行重新换行。这是 damon 文档语法清理系列的第 4 个补丁。</p><blockquote><p><strong>学习价值</strong>：展示了内核文档贡献的入门路径：即使不写代码，修复文档语法也是参与内核社区的方式。</p></blockquote><h3 id="f507911f1269-·-patch-v2-0-8-docs-damon-fix-grammar-and-typos" tabindex="-1"><code>f507911f1269</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-1-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 0/8] Docs: damon: fix grammar and typos</a> <a class="header-anchor" href="#f507911f1269-·-patch-v2-0-8-docs-damon-fix-grammar-and-typos" aria-label="Permalink to &quot;`f507911f1269` · [[PATCH v2 0/8] Docs: damon: fix grammar and typos](https://lore.kernel.org/all/20261103005940.91432-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>DAMON 文档语法与拼写错误清理系列补丁（v2），每个文档一个补丁，仅修改语法不改变语义。v2 根据评审意见更新并收集了 Reviewed-by 标签。</p><blockquote><p><strong>学习价值</strong>：典型的文档清理系列补丁流程，可学习多补丁系列的版本迭代与评审标签收集规范。</p></blockquote><h3 id="b411dbd09046-·-patch-v2-2-8-docs-admin-guide-mm-damon-stat-fix-pronoun-agreement" tabindex="-1"><code>b411dbd09046</code> · <a href="https://lore.kernel.org/all/20261103005940.91432-3-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH v2 2/8] Docs/admin-guide/mm/damon/stat: fix pronoun agreement</a> <a class="header-anchor" href="#b411dbd09046-·-patch-v2-2-8-docs-admin-guide-mm-damon-stat-fix-pronoun-agreement" aria-label="Permalink to &quot;`b411dbd09046` · [[PATCH v2 2/8] Docs/admin-guide/mm/damon/stat: fix pronoun agreement](https://lore.kernel.org/all/20261103005940.91432-3-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>修复 DAMON stat.rst 文档中的代词一致性问题，将 &quot;converts it&quot; 改为 &quot;them&quot; 以正确指代 access events，同时重新调整段落换行。</p><blockquote><p><strong>学习价值</strong>：说明内核文档对细节准确性的要求，适合学习 RST 文档维护规范。</p></blockquote><h3 id="_1d1ff773220e-·-patch-v2-mm-filemap-clear-page-cache-marks-once-when-removing-a-folio" tabindex="-1"><code>1d1ff773220e</code> · <a href="https://lore.kernel.org/all/20261102-bug-mm-filemap-init-marks-once-v2-1-985753b11173@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] mm/filemap: clear page cache marks once when removing a folio</a> <a class="header-anchor" href="#_1d1ff773220e-·-patch-v2-mm-filemap-clear-page-cache-marks-once-when-removing-a-folio" aria-label="Permalink to &quot;`1d1ff773220e` · [[PATCH v2] mm/filemap: clear page cache marks once when removing a folio](https://lore.kernel.org/all/20261102-bug-mm-filemap-init-marks-once-v2-1-985753b11173@gmail.com/)&quot;">​</a></h3><p><em>Qiliang Yuan (<a href="mailto:odys.yuan@gmail.com" target="_blank" rel="noreferrer">odys.yuan@gmail.com</a>)｜linux-mm</em></p><p>mm/filemap 中 page_cache_delete() 在 xas_store() 后无条件调用 xas_init_marks()，导致无 shadow entry 的 folio（如 POSIX_FADV_DONTNEED 和 drop_caches 路径）marks 被清除两次。补丁改为仅在存储 shadow entry 后调用 xas_init_marks()，在 4K folio 场景下可节省约 6% 的 clean page cache 回收时间。</p><blockquote><p><strong>学习价值</strong>：展示了 XArray marks 机制与 page cache 删除路径的交互，是学习 xas_store/xas_init_marks 语义和性能优化的好案例。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="bb8a5d45194b-·-patch-net-net-stmmac-rebuild-vlan-priority-steering-when-filters-change" tabindex="-1"><code>bb8a5d45194b</code> · <a href="https://lore.kernel.org/all/20261102-submit-stmmac-vlan-prio-v1-v1-1-2b37767e4e08@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] net: stmmac: rebuild VLAN priority steering when filters change</a> <a class="header-anchor" href="#bb8a5d45194b-·-patch-net-net-stmmac-rebuild-vlan-priority-steering-when-filters-change" aria-label="Permalink to &quot;`bb8a5d45194b` · [[PATCH net] net: stmmac: rebuild VLAN priority steering when filters change](https://lore.kernel.org/all/20261102-submit-stmmac-vlan-prio-v1-v1-1-2b37767e4e08@gmail.com/)&quot;">​</a></h3><p><em>James Hilliard (<a href="mailto:james.hilliard1@gmail.com" target="_blank" rel="noreferrer">james.hilliard1@gmail.com</a>)｜netdev</em></p><p>stmmac 驱动中 tc_del_vlan_flow() 传入零值优先级时，RX queue priority 回调会保留已删除规则的优先级映射，导致 VLAN 优先级 steering 状态不一致。补丁改为保存每条 VLAN 规则的优先级，并在插入和删除后从平台分配出发重建完整的 per-queue masks，重叠掩码沿用初始化时的 last-queue-wins 顺序。</p><blockquote><p><strong>学习价值</strong>：展示了 tc flower VLAN 过滤器与硬件 RX 队列映射的联动逻辑，以及状态重建优于增量修改的设计思路。</p></blockquote><h3 id="_5e32f778e1e0-·-patch-net-v4-7-7-net-mlx5e-psp-tso-replace-only-the-length-in-checksum-seed" tabindex="-1"><code>5e32f778e1e0</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-8-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 7/7] net/mlx5e: psp: tso: replace only the length in checksum seed</a> <a class="header-anchor" href="#_5e32f778e1e0-·-patch-net-v4-7-7-net-mlx5e-psp-tso-replace-only-the-length-in-checksum-seed" aria-label="Permalink to &quot;`5e32f778e1e0` · [[PATCH net v4 7/7] net/mlx5e: psp: tso: replace only the length in checksum seed](https://lore.kernel.org/all/20261103001143.246081-8-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>mlx5e PSP TSO 路径中，__tcp_transmit_skb() 用 socket 地址和总长度计算 checksum seed，而 mlx5e_psp_handle_tx_skb() 用包内 L3 头地址和单段长度重算。当 L3 daddr 是中间跳（如 IPv4 source route 或 IPv6 routing header）时地址差异会导致错误。补丁改为仅替换长度部分，保留原始地址计算。</p><blockquote><p><strong>学习价值</strong>：深入 PSP 加密、TSO 分段与 TCP checksum seed 的交互细节，是学习硬件 offload 与协议栈协作的高级案例。</p></blockquote><h3 id="_804dc479c6bc-·-patch-net-v4-6-7-selftests-drv-net-psp-test-that-ipv4-psp-packets-aren-t-fragmented" tabindex="-1"><code>804dc479c6bc</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 6/7] selftests: drv-net: psp: test that ipv4 psp packets aren&#39;t fragmented</a> <a class="header-anchor" href="#_804dc479c6bc-·-patch-net-v4-6-7-selftests-drv-net-psp-test-that-ipv4-psp-packets-aren-t-fragmented" aria-label="Permalink to &quot;`804dc479c6bc` · [[PATCH net v4 6/7] selftests: drv-net: psp: test that ipv4 psp packets aren&#39;t fragmented](https://lore.kernel.org/all/20261103001143.246081-7-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>新增 drv-net PSP 自测：构造需要分片的 IPv4 PSP TCP 包，验证其被丢弃（计入 IpFragFails）而非以明文发送。测试通过设置两倍于设备 MTU 的路由 MTU 并使用 IP_PMTUDISC_OMIT 迫使分片，不满足条件的场景自动跳过。</p><blockquote><p><strong>学习价值</strong>：演示了如何利用路由 MTU 与 IP_PMTUDISC_OMIT 构造分片场景，是学习网络自测编写技巧的好素材。</p></blockquote><h3 id="_228a74a954f3-·-patch-net-v4-5-7-selftests-drv-net-psp-test-ipv6-tcp-socket-with-extension-headers" tabindex="-1"><code>228a74a954f3</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-6-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 5/7] selftests: drv-net: psp: test ipv6 tcp socket with extension headers</a> <a class="header-anchor" href="#_228a74a954f3-·-patch-net-v4-5-7-selftests-drv-net-psp-test-ipv6-tcp-socket-with-extension-headers" aria-label="Permalink to &quot;`228a74a954f3` · [[PATCH net v4 5/7] selftests: drv-net: psp: test ipv6 tcp socket with extension headers](https://lore.kernel.org/all/20261103001143.246081-6-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>新增 drv-net PSP 自测：在 PSP TCP socket 上分三阶段测试 IPv6 扩展头（IPV6_DSTOPTS 和 IPV6_HOPOPTS）行为——无选项时正常收发，设置扩展头后包被丢弃且数据保持排队，移除选项后排队数据和新数据恢复发送。</p><blockquote><p><strong>学习价值</strong>：展示了 PSP 对 IPv6 扩展头的拒绝策略及对应自测设计，可学习分阶段验证内核行为变化的测试方法。</p></blockquote><h3 id="_302e0dc26bf6-·-patch-net-v4-4-7-ipv6-icmpv6-don-t-quote-decrypted-payload-in-icmpv6-errors" tabindex="-1"><code>302e0dc26bf6</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-5-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 4/7] ipv6: icmpv6: don&#39;t quote decrypted payload in icmpv6 errors</a> <a class="header-anchor" href="#_302e0dc26bf6-·-patch-net-v4-4-7-ipv6-icmpv6-don-t-quote-decrypted-payload-in-icmpv6-errors" aria-label="Permalink to &quot;`302e0dc26bf6` · [[PATCH net v4 4/7] ipv6: icmpv6: don&#39;t quote decrypted payload in icmpv6 errors](https://lore.kernel.org/all/20261103001143.246081-5-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>ICMPv6 错误会引用触发包的内容，若设备已解密该包（skb-&gt;decrypted 置位），错误消息会把明文 payload 发回网络造成泄露。补丁针对不同 offload 区分处理：kTLS RX offload 只解密 TCP payload，可引用 IPv6 头、扩展头和 TCP 头；PSP 加密覆盖 TCP 头则需进一步裁剪引用内容。</p><blockquote><p><strong>学习价值</strong>：揭示了 ICMP 错误引用机制与硬件解密 offload 结合时的信息泄露风险，是理解 skb-&gt;decrypted 标志与协议安全交互的好案例。</p></blockquote><h3 id="bd26f97d5836-·-patch-net-v4-3-7-ipv4-icmp-don-t-quote-decrypted-payload-in-icmp-errors" tabindex="-1"><code>bd26f97d5836</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-4-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 3/7] ipv4: icmp: don&#39;t quote decrypted payload in icmp errors</a> <a class="header-anchor" href="#bd26f97d5836-·-patch-net-v4-3-7-ipv4-icmp-don-t-quote-decrypted-payload-in-icmp-errors" aria-label="Permalink to &quot;`bd26f97d5836` · [[PATCH net v4 3/7] ipv4: icmp: don&#39;t quote decrypted payload in icmp errors](https://lore.kernel.org/all/20261103001143.246081-4-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>ICMP 错误消息引用触发包内容时，若 skb-&gt;decrypted 置位则可能把已解密的明文 payload 泄露回网络。补丁区分两种 offload：kTLS RX offload 下可引用 IP 头和 TCP 头（含选项），PSP 加密覆盖 TCP 头则引用内容需相应缩减，并省略 RFC 4884 扩展。</p><blockquote><p><strong>学习价值</strong>：与 IPv6 版本配套的 ICMPv4 安全修复，展示了协议错误路径中容易被忽视的明文泄露问题。</p></blockquote><h3 id="_671e787cec40-·-patch-net-v4-2-7-net-don-t-fragment-decrypted-skbs" tabindex="-1"><code>671e787cec40</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-3-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 2/7] net: don&#39;t fragment decrypted skbs</a> <a class="header-anchor" href="#_671e787cec40-·-patch-net-v4-2-7-net-don-t-fragment-decrypted-skbs" aria-label="Permalink to &quot;`671e787cec40` · [[PATCH net v4 2/7] net: don&#39;t fragment decrypted skbs](https://lore.kernel.org/all/20261103001143.246081-3-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>该补丁修复发送路径上已解密 skb 被分片后以明文发出的问题。skb-&gt;decrypted 标记表示设备需对包加密，但 ip_do_fragment() 产生的分片会丢失该标记，导致非首片分片可能未加密发出。由于加密需要 L4 头而分片缺少它，正确做法是丢弃而非明文发送。</p><blockquote><p><strong>学习价值</strong>：展示了 skb-&gt;decrypted 标志与 IP 分片路径的交互，是理解 crypto offload 与发送路径安全性的好案例。</p></blockquote><h3 id="_5ce5d7faa9e7-·-patch-net-v4-1-7-net-mlx5e-psp-drop-ipv6-packets-with-extension-headers" tabindex="-1"><code>5ce5d7faa9e7</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-2-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 1/7] net/mlx5e: psp: drop ipv6 packets with extension headers</a> <a class="header-anchor" href="#_5ce5d7faa9e7-·-patch-net-v4-1-7-net-mlx5e-psp-drop-ipv6-packets-with-extension-headers" aria-label="Permalink to &quot;`5ce5d7faa9e7` · [[PATCH net v4 1/7] net/mlx5e: psp: drop ipv6 packets with extension headers](https://lore.kernel.org/all/20261103001143.246081-2-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>mlx5e_psp_handle_tx_skb() 在处理带扩展头的 IPv6 包时会生成畸形包：nexthdr 位于扩展头链的最后一个头而非固定头中，导致 UDP+PSP 头插入位置错误。此外这类包在 mlx5 上会以明文发出，违背 tx association 的加密意图，因此应直接丢弃。</p><blockquote><p><strong>学习价值</strong>：深入展示了 PSP 加密 offload 与 IPv6 扩展头处理的细节，对学习 IPv6 头部结构和硬件 offload 安全很有帮助。</p></blockquote><h3 id="bdcde41eeb06-·-patch-net-v4-0-7-psp-tls-don-t-send-offloaded-contents-in-cleartext-1" tabindex="-1"><code>bdcde41eeb06</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 0/7] psp, tls: don&#39;t send offloaded contents in cleartext</a> <a class="header-anchor" href="#bdcde41eeb06-·-patch-net-v4-0-7-psp-tls-don-t-send-offloaded-contents-in-cleartext-1" aria-label="Permalink to &quot;`bdcde41eeb06` · [[PATCH net v4 0/7] psp, tls: don&#39;t send offloaded contents in cleartext](https://lore.kernel.org/all/20261103001143.246081-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>该系列补丁修复多个 crypto offload 路径上数据包可能以明文发送的问题，包括 IPv6 扩展头、IPv4 分片和 ICMP 等场景。作者在开发 socket-less PSP association 支持时发现这些问题，由于 tx/tls association 表达了加密意图，这些绕过加密的情况都需修复。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 PSP/TLS offload 明文泄漏的多种场景，适合系统性了解传输层加密 offload 的边界条件。</p></blockquote><h3 id="a22963a0823d-·-patch-v1-net-next-2-2-tcp-subtract-psp-sk-overhead-in-tcp-mtu-to-mss-and-tcp-mss-to-mtu" tabindex="-1"><code>a22963a0823d</code> · <a href="https://lore.kernel.org/all/20261103000712.658501-3-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 2/2] tcp: Subtract psp_sk_overhead() in __tcp_mtu_to_mss() and tcp_mss_to_mtu().</a> <a class="header-anchor" href="#a22963a0823d-·-patch-v1-net-next-2-2-tcp-subtract-psp-sk-overhead-in-tcp-mtu-to-mss-and-tcp-mss-to-mtu" aria-label="Permalink to &quot;`a22963a0823d` · [[PATCH v1 net-next 2/2] tcp: Subtract psp_sk_overhead() in __tcp_mtu_to_mss() and tcp_mss_to_mtu().](https://lore.kernel.org/all/20261103000712.658501-3-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>该补丁将 psp_sk_overhead() 的扣除从 icsk_ext_hdr_len 机制移到 __tcp_mtu_to_mss() 和 tcp_mss_to_mtu() 中，在 clamp 到 peer MSS 之前扣除。因为 PSP 是在 TCP_ESTABLISHED 之后升级的，PSP 与非 PSP 流共享相同的路由 MTU 和 advmss，原方案无法让两者同时达到 4K MSS 以支持 TCP_ZEROCOPY_RECEIVE。</p><blockquote><p><strong>学习价值</strong>：细致讲解 TCP MSS 计算中 clamp 顺序的影响，是理解 tcp_mtu_to_mss 与路径 MTU 协商机制的优秀材料。</p></blockquote><h3 id="_9984fad72cef-·-patch-v1-net-next-1-2-psp-check-pas-tx-spi-in-psp-sk-overhead" tabindex="-1"><code>9984fad72cef</code> · <a href="https://lore.kernel.org/all/20261103000712.658501-2-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 1/2] psp: Check pas-&gt;tx.spi in psp_sk_overhead().</a> <a class="header-anchor" href="#_9984fad72cef-·-patch-v1-net-next-1-2-psp-check-pas-tx-spi-in-psp-sk-overhead" aria-label="Permalink to &quot;`9984fad72cef` · [[PATCH v1 net-next 1/2] psp: Check pas-&gt;tx.spi in psp_sk_overhead().](https://lore.kernel.org/all/20261103000712.658501-2-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>该补丁让 psp_sk_overhead() 检查 pas-&gt;tx.spi 而不仅是 sk-&gt;psp_assoc 是否设置。因为在 psp_sock_assoc_set_rx() 与 psp_sock_set_tx_key() 之间调用 ipv6_update_options() 会导致 PSP 开销被重复累加到 icsk_ext_hdr_len，且此时 Tx 包仍以明文发送，不应计入开销。</p><blockquote><p><strong>学习价值</strong>：展示了 socket 选项更新路径中状态检查的竞态细节，对学习 TCP socket 生命周期与 PSP 关联状态机有参考价值。</p></blockquote><h3 id="_3ac2d27aa90d-·-patch-v1-net-next-0-2-tcp-let-non-psp-and-psp-share-mtu-and-advmss" tabindex="-1"><code>3ac2d27aa90d</code> · <a href="https://lore.kernel.org/all/20261103000712.658501-1-kuniyu@google.com/" target="_blank" rel="noreferrer">[PATCH v1 net-next 0/2] tcp: Let non-PSP and PSP share mtu and advmss.</a> <a class="header-anchor" href="#_3ac2d27aa90d-·-patch-v1-net-next-0-2-tcp-let-non-psp-and-psp-share-mtu-and-advmss" aria-label="Permalink to &quot;`3ac2d27aa90d` · [[PATCH v1 net-next 0/2] tcp: Let non-PSP and PSP share mtu and advmss.](https://lore.kernel.org/all/20261103000712.658501-1-kuniyu@google.com/)&quot;">​</a></h3><p><em>Kuniyuki Iwashima (<a href="mailto:kuniyu@google.com" target="_blank" rel="noreferrer">kuniyu@google.com</a>)｜netdev</em></p><p>该系列让 PSP 与非 PSP 流共享相同的 MTU 和 advmss 并都能达到 4K MSS。原方案中 psp_sk_overhead() 加在 icsk_ext_hdr_len 上并在 clamp 之后扣除，导致无论怎样配置路由都无法让两类流同时获得 4K MSS，破坏 TCP_ZEROCOPY_RECEIVE。修复方式是在 clamp 前扣除 PSP 开销。</p><blockquote><p><strong>学习价值</strong>：通过具体数值示例说明 MSS clamp 顺序问题，帮助理解 PSP 开销对 TCP 分段大小和零拷贝接收的影响。</p></blockquote><h3 id="_83c3eef3db4b-·-patch-net-net-usb-lan78xx-resume-phylink-on-non-reset-usb-resume" tabindex="-1"><code>83c3eef3db4b</code> · <a href="https://lore.kernel.org/all/20261102235133.23011-1-stefanomunari.sm@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] net: usb: lan78xx: resume phylink on non-reset USB resume</a> <a class="header-anchor" href="#_83c3eef3db4b-·-patch-net-net-usb-lan78xx-resume-phylink-on-non-reset-usb-resume" aria-label="Permalink to &quot;`83c3eef3db4b` · [[PATCH net] net: usb: lan78xx: resume phylink on non-reset USB resume](https://lore.kernel.org/all/20261102235133.23011-1-stefanomunari.sm@gmail.com/)&quot;">​</a></h3><p><em>Stefano Munari (<a href="mailto:stefanomunari.sm@gmail.com" target="_blank" rel="noreferrer">stefanomunari.sm@gmail.com</a>)｜netdev</em></p><p>lan78xx 驱动中 phylink_resume() 只在 lan78xx_reset_resume() 中调用，当 USB 设备在系统睡眠（如 s2idle）期间保持供电且 USB core 调用 .resume 时，PHY 停留在 HALTED 状态导致链路中断。补丁将 phylink_resume() 移到 lan78xx_resume() 末尾，两条恢复路径共用，并仅在接口打开时调用。</p><blockquote><p><strong>学习价值</strong>：展示了 USB 网络驱动的 suspend/resume 路径与 phylink 状态机的配合，是学习电源管理和 phylink 生命周期的实用案例。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="b4b445f2f3fd-·-patch-fs-ntfs3-advertise-nodump-in-the-statx-attributes-mask" tabindex="-1"><code>b4b445f2f3fd</code> · <a href="https://lore.kernel.org/all/20261103010437.55455-1-dennylin0707@gmail.com/" target="_blank" rel="noreferrer">[PATCH] fs/ntfs3: advertise nodump in the statx attributes mask</a> <a class="header-anchor" href="#b4b445f2f3fd-·-patch-fs-ntfs3-advertise-nodump-in-the-statx-attributes-mask" aria-label="Permalink to &quot;`b4b445f2f3fd` · [[PATCH] fs/ntfs3: advertise nodump in the statx attributes mask](https://lore.kernel.org/all/20261103010437.55455-1-dennylin0707@gmail.com/)&quot;">​</a></h3><p><em>Hungyu Lin (<a href="mailto:dennylin0707@gmail.com" target="_blank" rel="noreferrer">dennylin0707@gmail.com</a>)｜lkml</em></p><p>修复 ntfs3 的 ntfs_getattr()：当 ni-&gt;nodump 设置时会返回 STATX_ATTR_NODUMP 标志，但 attributes_mask 中未包含该位，导致 statx 调用者认为该属性不受支持。补丁将 STATX_ATTR_NODUMP 加入 attributes_mask，无论标志是否设置都予以通告。修复自 33f29fc7c67e 引入 fileattr 支持以来的问题。</p><blockquote><p><strong>学习价值</strong>：一个简洁的 statx 语义修复，帮助学习者理解 attributes 与 attributes_mask 两个字段的约定及其对用户态调用者的影响。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_8af380e2ede3-·-patch-v2-rust-io-mem-fix-exclusive-mmio-region-requests" tabindex="-1"><code>8af380e2ede3</code> · <a href="https://lore.kernel.org/all/20261102-b4-rust-iomem-origin-master-fix-v2-1-1428247a94d6@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: io: mem: Fix exclusive MMIO region requests</a> <a class="header-anchor" href="#_8af380e2ede3-·-patch-v2-rust-io-mem-fix-exclusive-mmio-region-requests" aria-label="Permalink to &quot;`8af380e2ede3` · [[PATCH v2] rust: io: mem: Fix exclusive MMIO region requests](https://lore.kernel.org/all/20261102-b4-rust-iomem-origin-master-fix-v2-1-1428247a94d6@gmail.com/)&quot;">​</a></h3><p><em>Kwanghoon Son (<a href="mailto:asdfkwang@gmail.com" target="_blank" rel="noreferrer">asdfkwang@gmail.com</a>)｜lkml</em></p><p>修复 Rust ExclusiveIoMem 抽象层的 MMIO 区域预留问题：原实现将区域预留挂在设备资源节点下而非全局 iomem_resource 树，导致 request_mem_region() 的全局视图看不到该预留。修改为直接从 iomem_resource 请求区域，与 C 侧 request_mem_region()/release_mem_region() 行为一致。可通过 QEMU arm64 virt 的 qemu,fw-cfg-mmio 节点复现。</p><blockquote><p><strong>学习价值</strong>：提醒 Rust 抽象必须精确对齐 C 内核的资源树语义，是理解 kernel resource 管理与 Rust for Linux 边界的好案例。</p></blockquote><h3 id="bbd61deaf120-·-patch-v3-rust-serdev-use-delta-for-timeouts" tabindex="-1"><code>bbd61deaf120</code> · <a href="https://lore.kernel.org/all/20261103011143.917147-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v3] rust: serdev: use Delta for timeouts</a> <a class="header-anchor" href="#bbd61deaf120-·-patch-v3-rust-serdev-use-delta-for-timeouts" aria-label="Permalink to &quot;`bbd61deaf120` · [[PATCH v3] rust: serdev: use Delta for timeouts](https://lore.kernel.org/all/20261103011143.917147-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>该补丁将 serdev Rust API 中 write_all() 和 wait_until_sent() 的超时参数从裸 Jiffies（c_ulong 别名）改为 Delta&lt;Jiffy&gt;，使单位显式化。C 侧将超时 0 视为无限等待，而 Rust API 不保留该语义：0 或负值被向上取整为 1 个 jiffy，需要无限等待时传入 Delta::from_jiffies(isize::MAX)（即 MAX_SCHEDULE_TIMEOUT）。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核 API 如何用类型系统消除单位歧义并重新设计 C 语义，是学习 Rust 抽象设计原则的好例子。</p></blockquote><h3 id="_8cc7b50baf25-·-patch-4-4-gpu-nova-core-gsp-cmdq-add-the-gmc-receive-path" tabindex="-1"><code>8cc7b50baf25</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-4-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 4/4] gpu: nova-core: gsp: cmdq: add the GMC receive path</a> <a class="header-anchor" href="#_8cc7b50baf25-·-patch-4-4-gpu-nova-core-gsp-cmdq-add-the-gmc-receive-path" aria-label="Permalink to &quot;`8cc7b50baf25` · [[PATCH 4/4] gpu: nova-core: gsp: cmdq: add the GMC receive path](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-4-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux</em></p><p>该补丁为 nova-core 的 GSP 命令队列添加 GMC（GPU Management Controller）接收路径，镜像已有的 rpc 子模块。GSP-RM 用 GMC 消息应答请求（命令字携带响应标志和请求 id），并触发 GMC 事件；启动期间 load-and-execute 事件会在等待 GSP_INIT 回复时到达，必须处理后 GSP-RM 才会应答。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 编写的 NVIDIA GSP 驱动中消息接收路径的设计，对学习内核中异步固件通信协议实现有参考价值。</p></blockquote><h3 id="_0477fcf733f1-·-patch-3-4-gpu-nova-core-gsp-cmdq-add-the-gmc-send-path" tabindex="-1"><code>0477fcf733f1</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-3-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 3/4] gpu: nova-core: gsp: cmdq: add the GMC send path</a> <a class="header-anchor" href="#_0477fcf733f1-·-patch-3-4-gpu-nova-core-gsp-cmdq-add-the-gmc-send-path" aria-label="Permalink to &quot;`0477fcf733f1` · [[PATCH 3/4] gpu: nova-core: gsp: cmdq: add the GMC send path](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-3-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux</em></p><p>该补丁为 nova-core 的 GSP 命令队列添加 GMC 发送路径，作为 rpc 子模块的兄弟模块。r000 启动协议要求驱动通过 GMC API 命令发送 GSP_INIT（携带驱动配置），GMC 与 RPC 命令共享命令队列和序列计数器，且 GMC 命令总是单个元素（无 continuation record）。该模块目前作为 dead code 构建，直到切换到 r000 协议。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 驱动中命令队列子模块的分层设计与逐步合入策略，对学习大型 Rust 内核驱动的架构组织有帮助。</p></blockquote><h3 id="cb51b5d962e1-·-patch-2-4-gpu-nova-core-gsp-add-the-gmc-api-header" tabindex="-1"><code>cb51b5d962e1</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-2-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 2/4] gpu: nova-core: gsp: add the GMC API header</a> <a class="header-anchor" href="#cb51b5d962e1-·-patch-2-4-gpu-nova-core-gsp-add-the-gmc-api-header" aria-label="Permalink to &quot;`cb51b5d962e1` · [[PATCH 2/4] gpu: nova-core: gsp: add the GMC API header](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-2-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux</em></p><p>为 nova-core 驱动添加 GMC（GPU Management Controller）API header 的 Rust 类型封装。GmcApiHeader 作为 GMCAPI_HEADER binding 之上的 newtype，用于支持 r000 固件中基于 GMC 协议的收发路径。作者将 binding 类型直接包装而非重新定义，并让 status 返回 Option 以避免语义歧义。</p><blockquote><p><strong>学习价值</strong>：展示了如何在 Rust 内核驱动中用 newtype 模式封装 bindgen 生成的 C binding，是学习 Rust-C 互操作的好例子。</p></blockquote><h3 id="addb648189af-·-patch-1-4-gpu-nova-core-gsp-fw-add-the-r000-bindings-for-the-gmc-api-header" tabindex="-1"><code>addb648189af</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-1-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 1/4] gpu: nova-core: gsp: fw: add the r000 bindings for the GMC API header</a> <a class="header-anchor" href="#addb648189af-·-patch-1-4-gpu-nova-core-gsp-fw-add-the-r000-bindings-for-the-gmc-api-header" aria-label="Permalink to &quot;`addb648189af` · [[PATCH 1/4] gpu: nova-core: gsp: fw: add the r000 bindings for the GMC API header](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-1-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux</em></p><p>为 nova-core 添加 r000 ABI 的第一部分 bindgen bindings，来源于 NVIDIA 开源驱动 OpenRM 的头文件。r000 是 GSP 固件 r615 及以后版本共享的统一 ABI 命名，避免随每次发布改名。当前驱动仍使用 r570 固件，但可同时针对 r570 bindings 编译。</p><blockquote><p><strong>学习价值</strong>：帮助理解固件 ABI 版本管理策略以及 bindgen 在内核 Rust 驱动中的实际应用流程。</p></blockquote><h3 id="c18d224c7e82-·-patch-0-4-gpu-nova-core-gsp-add-support-for-gmc-messages-1" tabindex="-1"><code>c18d224c7e82</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-0-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 0/4] gpu: nova-core: gsp: add support for GMC messages</a> <a class="header-anchor" href="#c18d224c7e82-·-patch-0-4-gpu-nova-core-gsp-add-support-for-gmc-messages-1" aria-label="Permalink to &quot;`c18d224c7e82` · [[PATCH 0/4] gpu: nova-core: gsp: add support for GMC messages](https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-0-189f9ff3bfd2@nvidia.com/)&quot;">​</a></h3><p><em>Alexandre Courbot (<a href="mailto:acourbot@nvidia.com" target="_blank" rel="noreferrer">acourbot@nvidia.com</a>)｜rust-for-linux</em></p><p>本系列从 John Hubbard 的 r000 系列 v3 中提取 patch 9-12，为 nova-core 添加 GMC GSP 消息协议支持，并 rebase 到最新的 drm-rust-next 分支。GMC 是 r000 固件用于 boot protocol 和新接口的消息类型，拥有独立 header。该系列不引入功能性变化，新代码在切换到 r000 前保持休眠状态。</p><blockquote><p><strong>学习价值</strong>：展示了大型 patch 系列如何拆分重组以便于 review，以及 DRM 子系统中休眠代码的渐进式合入策略。</p></blockquote><h3 id="_6f51da4a5f79-·-patch-2-2-rust-dmafence-replace-call-rcu-with-synchronize-rcu" tabindex="-1"><code>6f51da4a5f79</code> · <a href="https://lore.kernel.org/all/20261102150617.527772-4-phasta@kernel.org/" target="_blank" rel="noreferrer">[PATCH 2/2] rust: DmaFence: Replace call_rcu() with synchronize_rcu()</a> <a class="header-anchor" href="#_6f51da4a5f79-·-patch-2-2-rust-dmafence-replace-call-rcu-with-synchronize-rcu" aria-label="Permalink to &quot;`6f51da4a5f79` · [[PATCH 2/2] rust: DmaFence: Replace call_rcu() with synchronize_rcu()](https://lore.kernel.org/all/20261102150617.527772-4-phasta@kernel.org/)&quot;">​</a></h3><p><em>Philipp Stanner (<a href="mailto:phasta@kernel.org" target="_blank" rel="noreferrer">phasta@kernel.org</a>)｜rust-for-linux</em></p><p>将 Rust DmaFence 实现中手动的 call_rcu() 调用替换为 synchronize_rcu()。C 的 dma_fence 契约要求 fence 数据在 signal 后至少存活一个 RCU grace period，但 call_rcu() 的回调可能在 atomic context 中执行，不适合某些不能在原子上下文释放的驱动数据。结合 drm::JobQueue 中 DriverFence 与 Job 一一耦合的新设计，改用 synchronize_rcu() 更为合适。</p><blockquote><p><strong>学习价值</strong>：深入讲解 RCU 延迟释放与 atomic context 约束的权衡，是理解内核内存生命周期管理的优秀案例。</p></blockquote><h3 id="_2a18910f61dc-·-patch-1-2-rust-dmafence-don-t-drop-on-signal" tabindex="-1"><code>2a18910f61dc</code> · <a href="https://lore.kernel.org/all/20261102150617.527772-3-phasta@kernel.org/" target="_blank" rel="noreferrer">[PATCH 1/2] rust: DmaFence: Don&#39;t drop on signal</a> <a class="header-anchor" href="#_2a18910f61dc-·-patch-1-2-rust-dmafence-don-t-drop-on-signal" aria-label="Permalink to &quot;`2a18910f61dc` · [[PATCH 1/2] rust: DmaFence: Don&#39;t drop on signal](https://lore.kernel.org/all/20261102150617.527772-3-phasta@kernel.org/)&quot;">​</a></h3><p><em>Philipp Stanner (<a href="mailto:phasta@kernel.org" target="_blank" rel="noreferrer">phasta@kernel.org</a>)｜rust-for-linux</em></p><p>修改 Rust DmaFence 实现，取消在 signal 时立即 drop 的行为。原设计为严格遵守 dma_fence 只能 signal 一次的契约而在 signal 时 drop，但这导致 fence 数据必须以 RCU 延迟方式释放，而 fence 常在 atomic context（如中断处理程序）中被 signal，此时应尽快 signal 而非执行 drop。</p><blockquote><p><strong>学习价值</strong>：揭示了 Rust 抽象层如何与 C 内核契约（dma_fence 语义）磨合，对理解 DRM 同步原语和 Rust drop 时机问题很有价值。</p></blockquote><h3 id="_4b5b81737cb0-·-patch-0-2-rust-adjust-dma-buf-driverfence-drop" tabindex="-1"><code>4b5b81737cb0</code> · <a href="https://lore.kernel.org/all/20261102150617.527772-2-phasta@kernel.org/" target="_blank" rel="noreferrer">[PATCH 0/2] rust: Adjust dma_buf::DriverFence::drop()</a> <a class="header-anchor" href="#_4b5b81737cb0-·-patch-0-2-rust-adjust-dma-buf-driverfence-drop" aria-label="Permalink to &quot;`4b5b81737cb0` · [[PATCH 0/2] rust: Adjust dma_buf::DriverFence::drop()](https://lore.kernel.org/all/20261102150617.527772-2-phasta@kernel.org/)&quot;">​</a></h3><p><em>Philipp Stanner (<a href="mailto:phasta@kernel.org" target="_blank" rel="noreferrer">phasta@kernel.org</a>)｜rust-for-linux</em></p><p>为适配 drm::JobQueue 上游化需求而对 DmaFence 的 drop 行为进行调整的两补丁系列：一是取消 signal 时 drop，二是将 call_rcu() 替换为 synchronize_rcu()。修改集中在 rust/kernel/dma_buf/dma_fence.rs，已通过 JobQueue 和 dummy driver 测试。</p><blockquote><p><strong>学习价值</strong>：展示了上游化过程中依赖补丁系列的演进方式，可学习 dma_fence 生命周期与 atomic context 约束的交互。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_5a28ba00b284-·-next-20261102-linux-next" tabindex="-1"><code>5a28ba00b284</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261102-2026-11-02" target="_blank" rel="noreferrer">next-20261102: linux-next</a> <a class="header-anchor" href="#_5a28ba00b284-·-next-20261102-linux-next" aria-label="Permalink to &quot;`5a28ba00b284` · [next-20261102: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261102-2026-11-02)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 2 日发布 next-20261102 版本。linux-next 是主线合并前的集成测试树，汇集各子系统分支的待合并补丁。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 发布有助于了解即将进入主线的代码动态，是内核开发者日常关注的常规信息。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_02f00b3181dd-·-the-second-part-of-the-7-4-merge-window-1" tabindex="-1"><code>02f00b3181dd</code> · <a href="https://lwn.net/Articles/1102739/" target="_blank" rel="noreferrer">[$] The second part of the 7.4 merge window</a> <a class="header-anchor" href="#_02f00b3181dd-·-the-second-part-of-the-7-4-merge-window-1" aria-label="Permalink to &quot;`02f00b3181dd` · [[$] The second part of the 7.4 merge window](https://lwn.net/Articles/1102739/)&quot;">​</a></h3><p><em>daroc｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Linux 7.4 合并窗口于 11 月 1 日关闭，共合入 18,591 个非 merge changesets，几乎追平 7.3 周期 18,765 的历史纪录。其中 11,838 个落在合并窗口后半段，且大部分是各类 bug 修复，显示修复工作似乎正在挤占新特性的空间。尽管如此，窗口末期仍合入了不少新特性，也移除了一些旧功能。</p><blockquote><p><strong>学习价值</strong>：通过合并窗口统计可以观察内核开发节奏与 bug 修复占比趋势，是理解内核发布流程的直观素材。</p></blockquote><h3 id="_111aa59788e4-·-shutting-the-door-on-the-xcpe-botnet-threat-intelligence" tabindex="-1"><code>111aa59788e4</code> · <a href="https://lwn.net/Articles/1104847/" target="_blank" rel="noreferrer">Shutting the Door on the XCPE Botnet (Threat Intelligence)</a> <a class="header-anchor" href="#_111aa59788e4-·-shutting-the-door-on-the-xcpe-botnet-threat-intelligence" aria-label="Permalink to &quot;`111aa59788e4` · [Shutting the Door on the XCPE Botnet (Threat Intelligence)](https://lwn.net/Articles/1104847/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Google Threat Intelligence 博客详细介绍了刚被取缔的 XCPE botnet：Google 与行业合作伙伴摧毁了该后门，其曾将超过 130 万台机顶盒纳入僵尸网络。评估以高置信度认定该后门由 Android OEM/ODM 厂商 Videostrong Technology 出于牟利目的开发、部署和运营，并通过向犯罪团伙出售访问权限变现。</p><blockquote><p><strong>学习价值</strong>：属于供应链安全与 IoT 恶意软件案例，对理解嵌入式设备后门威胁模式有参考价值，但与内核代码本身关联较弱。</p></blockquote><h3 id="_8563f29ab924-·-managing-the-kernel-cve-flood-1" tabindex="-1"><code>8563f29ab924</code> · <a href="https://lwn.net/Articles/1100894/" target="_blank" rel="noreferrer">[$] Managing the kernel CVE flood</a> <a class="header-anchor" href="#_8563f29ab924-·-managing-the-kernel-cve-flood-1" aria-label="Permalink to &quot;`8563f29ab924` · [[$] Managing the kernel CVE flood](https://lwn.net/Articles/1100894/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>在 2026 Linux Plumbers Conference 上，Amazon 工程师 Dylan Johnson 和 Justinien Bouron 从维护 AWS 安全运行的角度讨论了如何应对海量 kernel CVE 披露。内核社区长期建议运行最新内核，这一策略在实践中确实有效——但只是勉强有效。</p><blockquote><p><strong>学习价值</strong>：展示了大规模生产环境如何实际处理内核 CVE 洪流，对理解内核漏洞管理流程与运维实践很有价值。</p></blockquote><h3 id="_2ea2c1b84163-·-tor-browser-16-0-released" tabindex="-1"><code>2ea2c1b84163</code> · <a href="https://lwn.net/Articles/1104846/" target="_blank" rel="noreferrer">Tor Browser 16.0 released</a> <a class="header-anchor" href="#_2ea2c1b84163-·-tor-browser-16-0-released" aria-label="Permalink to &quot;`2ea2c1b84163` · [Tor Browser 16.0 released](https://lwn.net/Articles/1104846/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Tor Browser 16.0 发布，这是首个基于 Firefox ESR 153 的稳定版本。新特性包括支持 64-bit Arm Linux、重新设计的设置界面，以及防止其他应用窥探浏览器活动的 generic window titles 功能；同时跟随 Firefox 终止对 32-bit x86 Linux 的支持。</p><blockquote><p><strong>学习价值</strong>：属于应用层浏览器发布新闻，与内核学习基本无关，仅可顺带了解 32-bit x86 支持在生态中的持续萎缩。</p></blockquote><h3 id="e476dbb4d194-·-security-updates-for-monday" tabindex="-1"><code>e476dbb4d194</code> · <a href="https://lwn.net/Articles/1104844/" target="_blank" rel="noreferrer">Security updates for Monday</a> <a class="header-anchor" href="#e476dbb4d194-·-security-updates-for-monday" aria-label="Permalink to &quot;`e476dbb4d194` · [Security updates for Monday](https://lwn.net/Articles/1104844/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora 等发行版发布了一批安全更新，涉及 firefox、kernel、kernel-rt、chromium、thunderbird、vim 等大量软件包。这是 LWN 例行的每日安全更新汇总。</p><blockquote><p><strong>学习价值</strong>：例行安全公告列表，信息密度低，仅可用于跟踪发行版层面的内核安全补丁动态。</p></blockquote><h3 id="ed5d354724a3-·-aerynos-2026-11-released-with-new-installer-option-other-improvements" tabindex="-1"><code>ed5d354724a3</code> · <a href="https://www.phoronix.com/news/AerynOS-2026.11" target="_blank" rel="noreferrer">AerynOS 2026.11 Released With New Installer Option, Other Improvements</a> <a class="header-anchor" href="#ed5d354724a3-·-aerynos-2026-11-released-with-new-installer-option-other-improvements" aria-label="Permalink to &quot;`ed5d354724a3` · [AerynOS 2026.11 Released With New Installer Option, Other Improvements](https://www.phoronix.com/news/AerynOS-2026.11)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AerynOS 2026.11 发布，并附带一篇详细介绍该发行版近期开发工作的博客文章，包含新的安装器选项等改进。AerynOS 是一个较新的原创 Linux 发行版。</p><blockquote><p><strong>学习价值</strong>：发行版发布新闻，与内核学习无直接关联。</p></blockquote><h3 id="db3dab7802df-·-radeon-radv-vulkan-driver-adopts-an-llm-policy" tabindex="-1"><code>db3dab7802df</code> · <a href="https://www.phoronix.com/news/RADV-Adopts-LLM-Policy" target="_blank" rel="noreferrer">Radeon RADV Vulkan Driver Adopts An LLM Policy</a> <a class="header-anchor" href="#db3dab7802df-·-radeon-radv-vulkan-driver-adopts-an-llm-policy" aria-label="Permalink to &quot;`db3dab7802df` · [Radeon RADV Vulkan Driver Adopts An LLM Policy](https://www.phoronix.com/news/RADV-Adopts-LLM-Policy)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Mesa 中为 AMD Radeon GPU 提供 Vulkan 支持的 RADV 驱动宣布了自己的 AI/LLM 代码贡献政策，规范大语言模型在驱动开发中的使用方式。</p><blockquote><p><strong>学习价值</strong>：反映开源社区对 AI 生成代码的态度演变，对了解图形驱动开发流程有一定参考意义，但与内核核心子系统关系不大。</p></blockquote><h3 id="_3b221c2fd1a0-·-freerdp-3-33-released-with-webassembly-support-huge-influx-of-activity-due-to-ai" tabindex="-1"><code>3b221c2fd1a0</code> · <a href="https://www.phoronix.com/news/FreeRDP-3.33" target="_blank" rel="noreferrer">FreeRDP 3.33 Released With WebAssembly Support, Huge Influx Of Activity Due To AI</a> <a class="header-anchor" href="#_3b221c2fd1a0-·-freerdp-3-33-released-with-webassembly-support-huge-influx-of-activity-due-to-ai" aria-label="Permalink to &quot;`3b221c2fd1a0` · [FreeRDP 3.33 Released With WebAssembly Support, Huge Influx Of Activity Due To AI](https://www.phoronix.com/news/FreeRDP-3.33)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>FreeRDP 3.33 发布，这是开源 Microsoft Remote Desktop Protocol (RDP) 实现的最新版本，新增 WebAssembly 支持。该项目近期因 AI 相关贡献而出现大量活动涌入。</p><blockquote><p><strong>学习价值</strong>：用户态远程桌面软件发布新闻，与内核学习基本无关。</p></blockquote><h3 id="_3b2a0314d074-·-kde-linux-nearing-its-beta-milestone-now-ships-with-ntsync-by-default" tabindex="-1"><code>3b2a0314d074</code> · <a href="https://www.phoronix.com/news/KDE-Linux-October-2026" target="_blank" rel="noreferrer">KDE Linux Nearing Its Beta Milestone, Now Ships With NTSYNC By Default</a> <a class="header-anchor" href="#_3b2a0314d074-·-kde-linux-nearing-its-beta-milestone-now-ships-with-ntsync-by-default" aria-label="Permalink to &quot;`3b2a0314d074` · [KDE Linux Nearing Its Beta Milestone, Now Ships With NTSYNC By Default](https://www.phoronix.com/news/KDE-Linux-October-2026)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE 开发者 Nate Graham 介绍了 KDE Linux 发行版的最新进展：该发行版已开发一年多，正接近 beta 里程碑，并默认搭载 NTSYNC。KDE Linux 定位为 KDE 的参考发行版。</p><blockquote><p><strong>学习价值</strong>：NTSYNC（Wine 相关的 NT 同步原语内核接口）默认启用值得留意，可作为了解该内核特性的线索。</p></blockquote><h3 id="_6a094e483e16-·-raspberry-pi-5-16gb-price-rises-to-385-usd" tabindex="-1"><code>6a094e483e16</code> · <a href="https://www.phoronix.com/news/Raspberry-Pi-5-16GB-385" target="_blank" rel="noreferrer">Raspberry Pi 5 16GB Price Rises To $385 USD</a> <a class="header-anchor" href="#_6a094e483e16-·-raspberry-pi-5-16gb-price-rises-to-385-usd" aria-label="Permalink to &quot;`6a094e483e16` · [Raspberry Pi 5 16GB Price Rises To $385 USD](https://www.phoronix.com/news/Raspberry-Pi-5-16GB-385)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Raspberry Pi 宣布新一轮涨价，受 RAM 短缺和价格上涨影响，Raspberry Pi 5 16GB 版本价格升至 385 美元。</p><blockquote><p><strong>学习价值</strong>：硬件市场新闻，与内核学习无关。</p></blockquote><h3 id="_34c5db29abac-·-rfc-patch-alsa-pcmtest-add-a-volume-control-with-event-fault-injection" tabindex="-1"><code>34c5db29abac</code> · <a href="https://lore.kernel.org/all/20261103011000.1012035-1-sammiee5311@gmail.com/" target="_blank" rel="noreferrer">[RFC PATCH] ALSA: pcmtest: Add a volume control with event fault injection</a> <a class="header-anchor" href="#_34c5db29abac-·-rfc-patch-alsa-pcmtest-add-a-volume-control-with-event-fault-injection" aria-label="Permalink to &quot;`34c5db29abac` · [[RFC PATCH] ALSA: pcmtest: Add a volume control with event fault injection](https://lore.kernel.org/all/20261103011000.1012035-1-sammiee5311@gmail.com/)&quot;">​</a></h3><p><em>HyeongJun An (<a href="mailto:sammiee5311@gmail.com" target="_blank" rel="noreferrer">sammiee5311@gmail.com</a>)｜lkml</em></p><p>为 ALSA pcmtest 虚拟驱动添加一个立体声 volume control，并引入两个故障注入参数：inject_ctl_no_event 使 put 回调错误地报告值未变化，inject_ctl_spurious_event 则每次都报告变化。这样 mixer-test selftest 的事件检查逻辑无需真实故障硬件即可被验证。参数关闭时 mixer-test 通过，任一开启时仅对应的事件检查失败。</p><blockquote><p><strong>学习价值</strong>：展示了如何用虚拟驱动加故障注入来测试内核自测代码的覆盖能力，是学习 ALSA control 事件机制与 kunit/selftest 实践的好例子。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>bdcde41eeb06</code> · <a href="https://lore.kernel.org/all/20261103001143.246081-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v4 0/7] psp, tls: don&#39;t send offloaded contents in cleartext</a></li><li><code>7e4e53192e64</code> · <a href="https://lore.kernel.org/all/20261103010216.3447716-1-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v3 00/10] liveupdate: Preserve tmpfs files across Live Update</a></li><li><code>c18d224c7e82</code> · <a href="https://lore.kernel.org/all/20261103-r000_rebase_on_cmdq-rpc-v1-0-189f9ff3bfd2@nvidia.com/" target="_blank" rel="noreferrer">[PATCH 0/4] gpu: nova-core: gsp: add support for GMC messages</a></li></ul>',263)])])}const f=a(l,[["render",n]]);export{h as __pageData,f as default};
